using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using SWBodyOrganizer;
namespace MasterMiao.Weld {
 public sealed class WeldModule:IWorkspaceModule {WeldView view;public string Id{get{return "weld-groups";}}public string Title{get{return "焊接体分组";}}public Control View{get{return view??(view=new WeldView());}}public bool IsBusy{get{return false;}}public bool CanClose(){return true;}public void Dispose(){if(view!=null)view.Dispose();}}
 public sealed class WeldView:UserControl {
  readonly WeldBridge bridge;readonly ListView groups=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=true};readonly ListView members=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=true};
  readonly Label status=new Label{Dock=DockStyle.Fill,AutoEllipsis=true,Text="连接当前装配体后，新建焊接组，再选中 SolidWorks 零件加入。",Padding=new Padding(8)};readonly Label title=new Label{AutoSize=true,Text="未连接装配体",Padding=new Padding(8)};bool refreshing;
  public WeldView(WeldBridge connection=null){bridge=connection??new WeldBridge();Dock=DockStyle.Fill;Padding=new Padding(14);Font=new Font("Microsoft YaHei UI",9);BackColor=Color.FromArgb(246,248,251);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,80));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,64));var head=new FlowLayoutPanel{Dock=DockStyle.Fill};Add(head,"连接当前装配体",()=>{bridge.Attach();title.Text=Path.GetFileName(bridge.Project.AssemblyPath)+" · "+bridge.Project.Configuration;RefreshGroups();status.Text="已连接。分组自动独立保存；小标记随装配体保存，不改变孔标注颜色。";});head.Controls.Add(title);layout.Controls.Add(head,0,0);
   var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};Add(bar,"新建焊接组",NewGroup);Add(bar,"编辑组",EditGroup);Add(bar,"加入 SW 选中零件",AddSelected);Add(bar,"移出选中成员",RemoveSelected);Add(bar,"删除所选组",DeleteGroups);Add(bar,"显示所选组标记",()=>Markers(true));Add(bar,"隐藏所选组标记",()=>Markers(false));Add(bar,"刷新标记",()=>{int n=bridge.SyncMarkers();RefreshMembers();status.Text="标记已刷新；未解析成员 "+n+" 项。请保存装配体以保存标记。";});Add(bar,"清除高亮",()=>bridge.ClearHighlight());Add(bar,"隐藏所选零件",()=>bridge.HideMembers(SelectedMembers()));Add(bar,"恢复隐藏",()=>bridge.RestoreHidden());layout.Controls.Add(bar,0,1);
   var split=new SplitContainer{Dock=DockStyle.Fill,Width=900,SplitterDistance=280};groups.Columns.Add("焊接组",220);groups.Columns.Add("成员",50);members.Columns.Add("零件实例",280);members.Columns.Add("所属焊接组",220);members.Columns.Add("配置",120);split.Panel1.Controls.Add(groups);split.Panel2.Controls.Add(members);layout.Controls.Add(split,0,2);layout.Controls.Add(status,0,3);Controls.Add(layout);
   groups.SelectedIndexChanged+=(s,e)=>{if(refreshing)return;Do(()=>{RefreshMembers();var selected=ChosenGroups();if(selected.Count>0){int n=bridge.Highlight(selected);status.Text="已高亮 "+selected.Count+" 组；高亮使用 SW 的六种选择色（超过六组循环），共享零件显示多个组编号。未解析 "+n+" 项。";}else bridge.ClearHighlight();});};members.SelectedIndexChanged+=(s,e)=>{if(refreshing||members.SelectedItems.Count==0)return;Do(()=>bridge.Highlight(ChosenGroups(),SelectedMembers().Select(x=>x.Id)));};
   Add(bar,"自动分组建议",SuggestGroups);groups.ContextMenuStrip=Menu(groups,true);members.ContextMenuStrip=Menu(members,false);
  }
  void Add(FlowLayoutPanel p,string text,Action action){var b=new Button{Text=text,AutoSize=true,Margin=new Padding(3)};b.Click+=(s,e)=>Do(action);p.Controls.Add(b);}
  void Do(Action action){try{action();}catch(Exception ex){status.Text=ex.GetBaseException().Message;}}
  List<WeldGroup> ChosenGroups(){bridge.Guard();return groups.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldGroup)x.Tag).ToList();}
  WeldGroup One(){var list=ChosenGroups();if(list.Count!=1)throw new InvalidOperationException("请选择一个焊接组。");return list[0];}
  List<WeldMember> SelectedMembers(){return members.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldMember)x.Tag).ToList();}
  int NextColor(){int[] colors={0xD07020,0x30A040,0x4060E0,0xC050B0,0x20B0D0,0xD0B030,0x8070E0,0x70A090};return colors.FirstOrDefault(c=>!bridge.Project.Groups.Any(g=>g.Color==c));}
  bool EditDialog(string caption,ref string name,ref int color,ref string remark){using(var dialog=new Form{Text=caption,Width=420,Height=240,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var label=new Label{Text="组名称",Left=18,Top=20,Width=65};var input=new TextBox{Text=name,Left=90,Top=18,Width=290};var notes=new TextBox{Text=remark,Left=90,Top=62,Width=290};var swatch=new Button{Text="选择颜色",Left=90,Top=104,Width=120,BackColor=ColorTranslator.FromWin32(color)};int chosen=color;swatch.Click+=(s,e)=>{using(var picker=new ColorDialog{Color=swatch.BackColor,FullOpen=true})if(picker.ShowDialog(dialog)==DialogResult.OK){chosen=ColorTranslator.ToWin32(picker.Color);swatch.BackColor=picker.Color;}};var ok=new Button{Text="保存",Left=210,Top=155,DialogResult=DialogResult.OK};dialog.Controls.AddRange(new Control[]{label,input,new Label{Text="备注",Left=18,Top=65},notes,swatch,ok,new Button{Text="取消",Left=300,Top=155,DialogResult=DialogResult.Cancel}});dialog.AcceptButton=ok;if(dialog.ShowDialog(this)!=DialogResult.OK)return false;name=input.Text.Trim();remark=notes.Text;color=chosen;return true;}}
  void NewGroup(){bridge.Guard();string name="焊接组 "+bridge.Project.NextNumber,remark="";int color=NextColor();if(!EditDialog("新建焊接组",ref name,ref color,ref remark))return;var g=WeldStore.AddGroup(bridge.Project,name,color);g.Remark=remark;bridge.Save();RefreshGroups(g.Id);}
  void EditGroup(){var g=One();string name=g.Name,remark=g.Remark;int color=g.Color;if(!EditDialog("编辑 "+g.Code,ref name,ref color,ref remark))return;if(name.Length==0||bridge.Project.Groups.Any(x=>x.Id!=g.Id&&(x.Name.Equals(name,StringComparison.OrdinalIgnoreCase)||x.Color==color)))throw new InvalidOperationException("名称为空、名称重复或颜色已被其他组使用。");g.Name=name;g.Color=color;g.Remark=remark;bridge.Save();bridge.SyncMarkers();RefreshGroups(g.Id);}
  void AddSelected(){var g=One();var selected=bridge.Selected();foreach(var m in selected)WeldStore.AddMember(g,m);bridge.Save();int missing=bridge.SyncMarkers();RefreshGroups(g.Id);status.Text="已加入 "+selected.Count+" 个零件；组内自动去重，其他组归属保留。未解析 "+missing+" 项。";}
  void RemoveSelected(){var g=One();var ids=SelectedMembers().Select(m=>m.Id).ToArray();bridge.RemoveMembers(g,ids);RefreshGroups(g.Id);}
  void DeleteGroups(){var list=ChosenGroups();if(list.Count==0)return;if(MessageBox.Show(this,"删除所选 "+list.Count+" 个组及其小标记？不会删除零件或其他组归属。","删除焊接组",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bridge.RemoveGroups(list.Select(g=>g.Id));RefreshGroups();}
  void Markers(bool visible){foreach(var g in ChosenGroups())g.MarkersVisible=visible;bridge.Save();bridge.SyncMarkers();}
  void SuggestGroups(){var group=One();var selected=bridge.Selected();if(selected.Count!=1)throw new InvalidOperationException("自动建议请先在 SolidWorks 中选择一个基准零件。");var seed=selected[0];using(var dialog=new Form{Text="以 "+seed.Instance+" 为基准查找候选",Width=850,Height=540,StartPosition=FormStartPosition.CenterParent}){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=75};var gap=new NumericUpDown{DecimalPlaces=2,Minimum=0,Maximum=10,Value=.2m,Width=75};var excluded=new TextBox{Text="螺钉,螺栓,螺母,垫圈,轴承,screw,bolt,nut,washer,bearing",Width=340};var scan=new Button{Text="查找邻近零件",AutoSize=true};bar.Controls.AddRange(new Control[]{new Label{Text="允许间隙(mm)",AutoSize=true,Padding=new Padding(3,6,0,0)},gap,new Label{Text="排除名称关键词",AutoSize=true,Padding=new Padding(3,6,0,0)},excluded,scan});var list=new ListView{Dock=DockStyle.Fill,View=System.Windows.Forms.View.Details,CheckBoxes=true,FullRowSelect=true};list.Columns.Add("候选零件",290);list.Columns.Add("间隙(mm)",100);list.Columns.Add("判断依据",330);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=70};var add=new Button{Text="确认加入当前组",AutoSize=true,Enabled=false};var hint=new Label{Text="只查找与基准零件直接邻近的候选，不沿接触链自动合并。请勾选确认；基准零件会一同加入。",AutoSize=true};footer.Controls.Add(hint);footer.SetFlowBreak(hint,true);footer.Controls.Add(add);var all=new Button{Text="全选",AutoSize=true};all.Click+=(s,e)=>{foreach(ListViewItem row in list.Items)row.Checked=true;};footer.Controls.Add(all);var none=new Button{Text="全不选",AutoSize=true};none.Click+=(s,e)=>{foreach(ListViewItem row in list.Items)row.Checked=false;};footer.Controls.Add(none);scan.Click+=(s,e)=>{scan.Enabled=false;try{list.Items.Clear();foreach(var candidate in bridge.Suggest(seed,(double)gap.Value,excluded.Text)){var row=new ListViewItem(candidate.Member.Instance){Tag=candidate};row.SubItems.Add(candidate.GapMm.ToString("0.000"));row.SubItems.Add(candidate.Reason);list.Items.Add(row);}hint.Text="找到 "+list.Items.Count+" 个候选。距离不能证明焊接关系，请勾选确认；基准零件会一同加入。";add.Enabled=true;}catch(Exception ex){hint.Text=ex.GetBaseException().Message;}finally{scan.Enabled=true;}};list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItems.Count==0)return;Do(()=>{var temp=new WeldGroup{Members=list.SelectedItems.Cast<ListViewItem>().Select(x=>((WeldCandidate)x.Tag).Member).ToList()};bridge.Highlight(new[]{temp});});};add.Click+=(s,e)=>{try{bridge.Guard();WeldStore.AddMember(group,seed);foreach(ListViewItem row in list.CheckedItems)WeldStore.AddMember(group,((WeldCandidate)row.Tag).Member);bridge.Save();bridge.SyncMarkers();dialog.DialogResult=DialogResult.OK;}catch(Exception ex){hint.Text=ex.GetBaseException().Message;}};dialog.Controls.Add(list);dialog.Controls.Add(footer);dialog.Controls.Add(bar);dialog.ShowDialog(this);RefreshGroups(group.Id);}}
  void RefreshGroups(string select=null){refreshing=true;try{groups.Items.Clear();foreach(var g in bridge.Project.Groups){var item=new ListViewItem(g.Code+"  "+g.Name){Tag=g,ForeColor=ColorTranslator.FromWin32(g.Color)};item.SubItems.Add(g.Members.Count.ToString());groups.Items.Add(item);if(g.Id==select)item.Selected=true;}}finally{refreshing=false;}RefreshMembers();}
  void RefreshMembers(){refreshing=true;try{members.Items.Clear();var selected=groups.SelectedItems.Cast<ListViewItem>().Select(x=>(WeldGroup)x.Tag);foreach(var m in selected.SelectMany(g=>g.Members).GroupBy(m=>m.Id).Select(g=>g.First())){var item=new ListViewItem(m.Instance){Tag=m};item.SubItems.Add(string.Join("、",bridge.Project.Groups.Where(g=>g.Members.Any(x=>x.Id==m.Id)).Select(g=>g.Code)));item.SubItems.Add(m.Configuration);members.Items.Add(item);}}finally{refreshing=false;}}
  ContextMenuStrip Menu(ListView list,bool isGroup){var menu=new ContextMenuStrip();foreach(var text in new[]{"全选","全不选","反选"}){var item=new ToolStripMenuItem(text);item.Click+=(s,e)=>{refreshing=true;try{foreach(ListViewItem row in list.Items)row.Selected=text=="全选"||(text=="反选"&&!row.Selected);}finally{refreshing=false;}Do(()=>{if(isGroup){RefreshMembers();bridge.Highlight(ChosenGroups());}else bridge.Highlight(ChosenGroups(),SelectedMembers().Select(m=>m.Id));});};menu.Items.Add(item);}var remove=new ToolStripMenuItem(isGroup?"删除所选组":"移出当前组");remove.Click+=(s,e)=>Do(isGroup?(Action)DeleteGroups:RemoveSelected);menu.Items.Add(remove);return menu;}
  protected override void Dispose(bool disposing){if(disposing)bridge.Dispose();base.Dispose(disposing);}
 }
}
